enum CapabilityStatus{live,simulated,planned,researchPrototype,historical,notConnected}extension CapabilityStatusLabel on CapabilityStatus{String get label=>switch(this){CapabilityStatus.live=>'LIVE',CapabilityStatus.simulated=>'SIMULATED',CapabilityStatus.planned=>'PLANNED',CapabilityStatus.researchPrototype=>'RESEARCH PROTOTYPE',CapabilityStatus.historical=>'HISTORICAL',CapabilityStatus.notConnected=>'NOT_CONNECTED'};}
